<template>
  <div class="page"><h2 class="page-title">本周执行与动态调整</h2><p class="muted">先看预算执行；只有发生计划外支出、收入变化或目标变化时，才需要重新规划。</p>
    <EmptyGuide v-if="ready && !activePlans.length" description="还没有正在执行的预算" hint="请先生成候选预算并确认启用。" action="/budgets" action-text="生成预算方案" />
    <template v-else-if="ready">
      <div class="card section"><div class="section-heading"><div><h3>本周与历史执行情况</h3><p class="muted">实际消费超过预算或财务条件改变时，系统会建议重新规划；小幅偏差无需频繁修改。</p></div><el-button @click="loadExecution">刷新</el-button></div>
        <el-table :data="execution" empty-text="当前计划尚无已发生周"><el-table-column prop="week_start" label="周开始"/><el-table-column label="计划预算"><template #default="s">{{formatMoney(s.row.budget_minor)}}</template></el-table-column><el-table-column label="实际消费"><template #default="s">{{formatMoney(s.row.actual_minor)}}</template></el-table-column><el-table-column label="相差"><template #default="s">{{formatMoney(s.row.absolute_variance_minor)}}</template></el-table-column><el-table-column label="执行状态"><template #default="s"><el-tag :type="statusType(s.row.status)">{{executionName(s.row.status)}}</el-tag></template></el-table-column></el-table>
      </div>
      <el-collapse class="section" v-model="openPanels"><el-collapse-item title="记录财务变化并预览影响" name="event"><div class="card flat-card">
        <el-steps :active="candidate?2:eventIds.length?1:0" finish-status="success" simple><el-step title="记录变化"/><el-step title="预览新方案"/><el-step title="确认启用"/></el-steps>
        <el-form label-position="top" class="section"><div class="grid form-grid"><el-form-item label="变化类型"><el-select v-model="event.type"><el-option label="计划外支出" value="unplanned_expense"/><el-option label="临时额外收入" value="extra_income"/><el-option label="收入下降" value="income_decrease"/><el-option label="收入增加" value="income_increase"/><el-option label="储蓄金额目标变化" value="goal_amount_change"/><el-option label="完成日期变化" value="goal_date_change"/><el-option label="预算底线变化" value="budget_constraint_change"/></el-select></el-form-item><el-form-item v-if="needsAmount" label="变化金额"><el-input v-model="event.amount"><template #append>元</template></el-input></el-form-item><el-form-item label="当前可用于目标的存款"><el-input v-model="currentSavings"><template #append>元</template></el-input></el-form-item><el-form-item label="从哪一周开始调整"><el-date-picker v-model="nextWeek" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="希望多久内逐步恢复"><el-select v-model="horizon"><el-option label="未来2周" :value="2"/><el-option label="未来4周（推荐）" :value="4"/><el-option label="全部剩余时间" value="all"/></el-select></el-form-item><el-form-item label="非敏感说明（可选）"><el-input v-model="event.note" maxlength="200"/></el-form-item></div><el-alert v-if="!needsAmount" title="请先在“目标与底线”页保存新条件，再回来记录变化原因。" type="info" :closable="false"/><div class="actions"><el-button :disabled="eventIds.length>0" @click="recordEvent">1. 记录变化</el-button><el-button type="primary" :loading="loading" :disabled="!eventIds.length" @click="preview">2. 预览调整影响</el-button></div></el-form>
      </div></el-collapse-item></el-collapse>
      <div v-if="candidate" class="card section"><el-result v-if="!candidate.feasible" icon="warning" title="变化发生后，原目标暂时无法实现"><template #sub-title><p>目前最高预计可达到 {{formatMoney(candidate.maximum_achievable_target_minor)}}；保持原目标还需增加约 {{formatMoney(candidate.required_additional_income_minor)}}。可以延后日期、降低目标或调整预算底线。</p></template><template #extra><el-button @click="$router.push('/goals')">调整目标条件</el-button></template></el-result><template v-else><h3>预览：旧方案与新方案</h3><p class="muted">这一步还没有替换当前预算，请确认变化是否可接受。</p><el-descriptions border :column="3"><el-descriptions-item label="原剩余预算">{{formatMoney(candidate.difference.old_future_budget_minor)}}</el-descriptions-item><el-descriptions-item label="新剩余预算">{{formatMoney(candidate.difference.new_future_budget_minor)}}</el-descriptions-item><el-descriptions-item label="预计恢复时间">{{candidate.recovery_metrics.weeks_to_recover??'无法在期限内恢复'}} 周</el-descriptions-item><el-descriptions-item label="原风险">{{riskName(candidate.difference.old_risk_level)}}</el-descriptions-item><el-descriptions-item label="新风险">{{riskName(candidate.difference.new_risk_level)}}</el-descriptions-item><el-descriptions-item label="预算总变化">{{formatMoney(candidate.difference.total_adjustment_minor)}}</el-descriptions-item></el-descriptions><div class="activation-box"><span>确认后生成新版本，旧方案仍保留在“方案记录”。</span><el-button type="primary" @click="confirm">3. 确认并启用新方案</el-button></div></template></div>
    </template>
  </div>
</template>
<script setup>
import { computed,onMounted,reactive,ref } from 'vue';import { useRouter } from 'vue-router';import { ElMessage,ElMessageBox } from 'element-plus';import { api } from '../api/client.js';import { formatMoney,yuanToMinor } from '../utils/money.js';import { riskLabels } from '../utils/display.js';import EmptyGuide from '../components/EmptyGuide.vue'
const router=useRouter(),plans=ref([]),planId=ref(),event=reactive({type:'unplanned_expense',amount:'500',note:''}),eventIds=ref([]),currentSavings=ref('5000'),nextWeek=ref(nextMonday()),horizon=ref(4),candidate=ref(),loading=ref(false),execution=ref([]),ready=ref(false),openPanels=ref([])
const activePlans=computed(()=>plans.value.filter(x=>x.is_current));const needsAmount=computed(()=>!['goal_date_change','budget_constraint_change'].includes(event.type));function nextMonday(){const d=new Date(),add=(8-d.getDay())%7||7;d.setDate(d.getDate()+add);return d.toISOString().slice(0,10)}const riskName=v=>riskLabels[v]||v||'暂无';const executionName=v=>({normal:'按计划执行',minor_variance:'有小幅偏差',replan_recommended:'建议重新规划'}[v]||v);const statusType=v=>v==='replan_recommended'?'danger':v==='minor_variance'?'warning':'success'
onMounted(async()=>{try{plans.value=(await api.get('/budgets')).items;planId.value=activePlans.value[0]?.id;await loadExecution()}finally{ready.value=true}})
async function loadExecution(){execution.value=planId.value?(await api.get(`/budgets/${planId.value}/execution`)).items:[]}
async function recordEvent(){const p=activePlans.value.find(x=>x.id===planId.value);if(!p)return ElMessage.error('请选择当前计划');try{const r=await api.post('/events',{goal_id:p.goal_id,event_type:event.type,amount_minor:needsAmount.value?yuanToMinor(event.amount):null,event_date:new Date().toISOString().slice(0,10),safe_note:event.note||null});eventIds.value=[r.id];ElMessage.success('变化已记录，现在可以预览影响')}catch(e){ElMessage.error(e.message)}}
function payload(){return{event_ids:eventIds.value,current_savings_minor:yuanToMinor(currentSavings.value),next_open_week:nextWeek.value,adjustment_mode:'balanced',recovery_horizon_weeks:horizon.value==='all'?null:horizon.value}}
async function preview(){loading.value=true;try{candidate.value=await api.post(`/budgets/${planId.value}/replan-preview`,payload())}catch(e){ElMessage.error(e.message)}finally{loading.value=false}}
async function confirm(){try{await ElMessageBox.confirm('确认后新方案将开始执行，旧方案会保留为历史版本。','确认启用新方案',{confirmButtonText:'确认启用',cancelButtonText:'继续比较',type:'warning'});await api.post(`/budgets/${planId.value}/replans`,payload());ElMessage.success('新预算方案已启用');router.push('/history')}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(e.message)}}
</script>
